parameters.jsCode:
// Prepare original CV and target job for truthful section-wise tailoring
const input = $input.first().json;
const originalCv = input.original_cv_tex || '';
const job = input.selected_job || {};

if (!originalCv || !job.job_title) {
  throw new Error('CONTRACT ERROR: Missing original_cv_tex or selected_job');
}

return [{ json: { original_cv_tex: originalCv, job: job } }];

parameters.prompt:
=You are an expert technical CV writer. Tailor the following LaTeX CV for the vacancy below.

CRITICAL CONSTRAINTS:
1. NEVER invent or hallucinate any employer, skill, degree, year, or project not in the original CV.
2. Only re-order, emphasize, and highlight genuine matching experience.
3. Preserve valid LaTeX syntax.
4. Write a tailored 3-paragraph cover letter.

JOB:
Title: {{ $json.job.job_title }}
Company: {{ $json.job.company }}
Description: {{ $json.job.description }}

ORIGINAL CV:
{{ $json.original_cv_tex }}

