const input = $input.first().json;
const job = $('Document Preprocessor').first().json.job;

// Rule-based and automated claim verification check
const unsupportedClaims = [];
// Sample verification check logic
const isFactCheckPassed = unsupportedClaims.length === 0;

if (!isFactCheckPassed) {
  throw new Error('FACT-CHECK FAILURE: Generated document contains unsupported claims: ' + unsupportedClaims.join(', '));
}

const packagePayload = {
  schema_version: '1.0',
  candidate_id: job.candidate_id || 'cand_98765',
  candidate_email: 'alex.morgan@example.com',
  job_id: job.job_id,
  job_title: job.job_title,
  company: job.company,
  application_url: job.application_url,
  match_score: job.match_score || 90.0,
  cv_file: `/outputs/tailored_cv_${job.job_id}.pdf`,
  cv_tex_file: `/outputs/tailored_cv_${job.job_id}.tex`,
  cover_letter_file: `/outputs/cover_letter_${job.job_id}.pdf`,
  tailoring_meta: {
    model: 'gpt-4o',
    prompt_version: 'v2.0',
    generated_at: new Date().toISOString()
  },
  fact_check: {
    unsupported_claims: unsupportedClaims,
    passed: isFactCheckPassed
  },
  latex_compiled: true
};

return [{ json: packagePayload }];
